INSERT OR REPLACE INTO [pages] (id, data) VALUES ('page-dmca-id', '{"_id":"6a7a0ca67d43640ecfff206a","id":"page-dmca-id","title":"DMCA","slug":"dmca","content":"<h1>DMCA / Copyright Notice</h1><h2>Pemberitahuan Hak Cipta</h2><p>Website ini adalah situs <strong>fansub non-komersial</strong> yang dibuat oleh penggemar untuk tujuan hiburan dan pembelajaran bahasa.</p><p>Seluruh video, karakter, logo, dan materi terkait <strong>Doraemon</strong> dan <strong>Crayon Shin-chan</strong> merupakan <strong>hak cipta milik pemegang lisensi resmi masing-masing</strong>. Kami tidak mengklaim kepemilikan atas konten tersebut.</p><p>Website ini <strong>tidak menyimpan file video di server sendiri</strong>. Semua konten video ditautkan atau di-embed dari pihak ketiga.</p><hr /><h2>DMCA (Digital Millennium Copyright Act)</h2><p>Kami menghormati hak kekayaan intelektual dan akan <strong>segera menindaklanjuti</strong> setiap pemberitahuan pelanggaran hak cipta yang sah.</p><p>Apabila Anda adalah pemilik hak cipta atau perwakilan resminya dan merasa bahwa konten di website ini melanggar hak cipta, silakan ajukan permintaan penghapusan (DMCA Takedown) dengan menyertakan informasi berikut:</p><ol><li><p>Identitas pemilik hak cipta atau perwakilan resmi.</p></li><li><p>Deskripsi karya berhak cipta yang diklaim dilanggar.</p></li><li><p>URL halaman di website kami yang berisi konten yang dimaksud.</p></li><li><p>Pernyataan bahwa informasi yang diberikan adalah benar dan Anda berwenang bertindak atas nama pemilik hak cipta.</p></li></ol><p>Permintaan yang lengkap dan valid akan kami proses <strong>secepat mungkin</strong> dengan melakukan penghapusan atau penonaktifan konten terkait.</p><hr /><h2>Donasi (Opsional)</h2><p>Website ini bersifat <strong>non-komersial</strong>. Donasi yang tersedia bersifat <strong>sukarela</strong> dan hanya digunakan untuk membantu biaya operasional seperti domain dan server.</p><p>Donasi <strong>tidak memberikan akses khusus</strong>, tidak membuka konten, dan tidak mempengaruhi ketersediaan episode apa pun.</p><hr /><h2>Kontak</h2><p>Untuk permintaan DMCA atau hal terkait hak cipta, silakan hubungi kami melalui:</p><ul><li><p>Email:&nbsp;<a href=\"mailto:shindoranesub@gmail.com\">shindoranesub@gmail.com</a></p></li><li><p>Form Kontak: <strong>/contact</strong></p></li></ul><hr /><h2>Penutup</h2><p>Dengan mengakses website ini, Anda memahami dan menyetujui bahwa semua konten adalah milik pemegang hak cipta resmi dan akan dihapus apabila ada permintaan yang sah dari pihak terkait.</p><p>Terima kasih atas pengertiannya.</p><p><br /></p><h1>DMCA / Copyright Notice</h1><h2>Copyright Disclaimer</h2><p>This website is a <strong>non-commercial fansub website</strong> created by fans for entertainment and language learning purposes only.</p><p>All videos, characters, logos, and related materials of <strong>Doraemon</strong> and <strong>Crayon Shin-chan</strong> are the <strong>property of their respective copyright holders</strong>. We do not claim ownership of any copyrighted content displayed on this site.</p><p>This website <strong>does not host any video files on its own servers</strong>. All video content is embedded or linked from third-party sources.</p><hr /><h2>DMCA (Digital Millennium Copyright Act)</h2><p>We respect intellectual property rights and will <strong>promptly respond</strong> to valid copyright infringement notices.</p><p>If you are a copyright owner or an authorized representative and believe that any content on this website infringes your copyright, please submit a DMCA takedown request containing the following information:</p><ol><li><p>Identification of the copyrighted work claimed to have been infringed.</p></li><li><p>The exact URL(s) on our website where the allegedly infringing content is located.</p></li><li><p>Identification and contact information of the copyright owner or authorized agent.</p></li><li><p>A statement that you have a good-faith belief that the use of the material is not authorized by the copyright owner, its agent, or the law.</p></li><li><p>A statement that the information provided is accurate and that you are authorized to act on behalf of the copyright owner.</p></li></ol><p>Upon receipt of a complete and valid notice, we will <strong>remove or disable access</strong> to the reported content as quickly as possible.</p><hr /><h2>Donations (Optional)</h2><p>This website operates on a <strong>non-commercial basis</strong>. Any donation links provided are <strong>completely voluntary</strong> and are used solely to help cover operational costs such as domain and server expenses.</p><p>Donations <strong>do not provide special access</strong>, do not unlock content, and do not affect the availability of any episodes.</p><hr /><h2>Contact Information</h2><p>For DMCA notices or copyright-related concerns, please contact us at:</p><ul><li><p>Email: <strong><a href=\"mailto:shindoranesub@gmail.com\">shindoranesub@gmail.com</a></strong></p></li><li><p>Contact Page: <strong>/contact</strong></p></li></ul><hr /><h2>Final Note</h2><p>By accessing this website, you acknowledge that all content belongs to the respective copyright holders and that any reported content will be removed upon receiving a valid request.</p><p>Thank you for your understanding.</p>","showInFooter":true,"createdAt":"2026-08-10T17:38:46.525Z"}');
INSERT OR REPLACE INTO [pages] (id, data) VALUES ('page-privacy-id', '{"_id":"6a7a0ca67d43640ecfff206b","id":"page-privacy-id","title":"Privacy Policy","slug":"privacy-policy","content":"<h1>Privacy Policy</h1>\n<p>Last updated: January 18, 2026</p>\n<p>This Privacy Policy describes Our policies and procedures on the collection, use and disclosure of Your information when You use the Service and tells You about Your privacy rights and how the law protects You.</p>\n<p>We use Your Personal data to provide and improve the Service. By using the Service, You agree to the collection and use of information in accordance with this Privacy Policy. This Privacy Policy has been created with the help of the <a href=\"https://www.termsfeed.com/privacy-policy-generator/\" target=\"_blank\">Privacy Policy Generator</a>.</p>\n<h2>Interpretation and Definitions</h2>\n<h3>Interpretation</h3>\n<p>The words whose initial letters are capitalized have meanings defined under the following conditions. The following definitions shall have the same meaning regardless of whether they appear in singular or in plural.</p>\n<h3>Definitions</h3>\n<p>For the purposes of this Privacy Policy:</p>\n<ul>\n<li>\n<p><strong>Account</strong> means a unique account created for You to access our Service or parts of our Service.</p>\n</li>\n<li>\n<p><strong>Affiliate</strong> means an entity that controls, is controlled by, or is under common control with a party, where \"control\" means ownership of 50% or more of the shares, equity interest or other securities entitled to vote for election of directors or other managing authority.</p>\n</li>\n<li>\n<p><strong>Company</strong> (referred to as either \"the Company\", \"We\", \"Us\" or \"Our\" in this Agreement) refers to ShinDora Nesub.</p>\n</li>\n<li>\n<p><strong>Cookies</strong> are small files that are placed on Your computer, mobile device or any other device by a website, containing the details of Your browsing history on that website among its many uses.</p>\n</li>\n<li>\n<p><strong>Country</strong> refers to:  Indonesia</p>\n</li>\n<li>\n<p><strong>Device</strong> means any device that can access the Service such as a computer, a cell phone or a digital tablet.</p>\n</li>\n<li>\n<p><strong>Personal Data</strong> is any information that relates to an identified or identifiable individual.</p>\n</li>\n<li>\n<p><strong>Service</strong> refers to the Website.</p>\n</li>\n<li>\n<p><strong>Service Provider</strong> means any natural or legal person who processes the data on behalf of the Company. It refers to third-party companies or individuals employed by the Company to facilitate the Service, to provide the Service on behalf of the Company, to perform services related to the Service or to assist the Company in analyzing how the Service is used.</p>\n</li>\n<li>\n<p><strong>Usage Data</strong> refers to data collected automatically, either generated by the use of the Service or from the Service infrastructure itself (for example, the duration of a page visit).</p>\n</li>\n<li>\n<p><strong>Website</strong> refers to ShinDora Nesub, accessible from <a href=\"shindoranesub.my.id\" rel=\"external nofollow noopener\" target=\"_blank\">shindoranesub.my.id</a></p>\n</li>\n<li>\n<p><strong>You</strong> means the individual accessing or using the Service, or the company, or other legal entity on behalf of which such individual is accessing or using the Service, as applicable.</p>\n</li>\n</ul>\n<h2>Collecting and Using Your Personal Data</h2>\n<h3>Types of Data Collected</h3>\n<h4>Personal Data</h4>\n<p>While using Our Service, We may ask You to provide Us with certain personally identifiable information that can be used to contact or identify You. Personally identifiable information may include, but is not limited to:</p>\n<ul>\n<li>\n<p>Email address</p>\n</li>\n<li>\n<p>Usage Data</p>\n</li>\n</ul>\n<h4>Usage Data</h4>\n<p>Usage Data is collected automatically when using the Service.</p>\n<p>Usage Data may include information such as Your Device''s Internet Protocol address (e.g. IP address), browser type, browser version, the pages of our Service that You visit, the time and date of Your visit, the time spent on those pages, unique device identifiers and other diagnostic data.</p>\n<p>When You access the Service by or through a mobile device, We may collect certain information automatically, including, but not limited to, the type of mobile device You use, Your mobile device''s unique ID, the IP address of Your mobile device, Your mobile operating system, the type of mobile Internet browser You use, unique device identifiers and other diagnostic data.</p>\n<p>We may also collect information that Your browser sends whenever You visit Our Service or when You access the Service by or through a mobile device.</p>\n<h4>Tracking Technologies and Cookies</h4>\n<p>We use Cookies and similar tracking technologies to track the activity on Our Service and store certain information. Tracking technologies We use include beacons, tags, and scripts to collect and track information and to improve and analyze Our Service. The technologies We use may include:</p>\n<ul>\n<li><strong>Cookies or Browser Cookies.</strong> A cookie is a small file placed on Your Device. You can instruct Your browser to refuse all Cookies or to indicate when a Cookie is being sent. However, if You do not accept Cookies, You may not be able to use some parts of our Service. Unless you have adjusted Your browser setting so that it will refuse Cookies, our Service may use Cookies.</li>\n<li><strong>Web Beacons.</strong> Certain sections of our Service and our emails may contain small electronic files known as web beacons (also referred to as clear gifs, pixel tags, and single-pixel gifs) that permit the Company, for example, to count users who have visited those pages or opened an email and for other related website statistics (for example, recording the popularity of a certain section and verifying system and server integrity).</li>\n</ul>\n<p>Cookies can be \"Persistent\" or \"Session\" Cookies. Persistent Cookies remain on Your personal computer or mobile device when You go offline, while Session Cookies are deleted as soon as You close Your web browser. You can learn more about cookies on <a href=\"https://www.termsfeed.com/blog/cookies/#What_Are_Cookies\" target=\"_blank\">TermsFeed website</a> article.</p>\n<p>We use both Session and Persistent Cookies for the purposes set out below:</p>\n<ul>\n<li>\n<p><strong>Necessary / Essential Cookies</strong></p>\n<p>Type: Session Cookies</p>\n<p>Administered by: Us</p>\n<p>Purpose: These Cookies are essential to provide You with services available through the Website and to enable You to use some of its features. They help to authenticate users and prevent fraudulent use of user accounts. Without these Cookies, the services that You have asked for cannot be provided, and We only use these Cookies to provide You with those services.</p>\n</li>\n<li>\n<p><strong>Cookies Policy / Notice Acceptance Cookies</strong></p>\n<p>Type: Persistent Cookies</p>\n<p>Administered by: Us</p>\n<p>Purpose: These Cookies identify if users have accepted the use of cookies on the Website.</p>\n</li>\n<li>\n<p><strong>Functionality Cookies</strong></p>\n<p>Type: Persistent Cookies</p>\n<p>Administered by: Us</p>\n<p>Purpose: These Cookies allow us to remember choices You make when You use the Website, such as remembering your login details or language preference. The purpose of these Cookies is to provide You with a more personal experience and to avoid You having to re-enter your preferences every time You use the Website.</p>\n</li>\n</ul>\n<p>For more information about the cookies we use and your choices regarding cookies, please visit our Cookies Policy or the Cookies section of our Privacy Policy.</p>\n<h3>Use of Your Personal Data</h3>\n<p>The Company may use Personal Data for the following purposes:</p>\n<ul>\n<li>\n<p><strong>To provide and maintain our Service</strong>, including to monitor the usage of our Service.</p>\n</li>\n<li>\n<p><strong>To manage Your Account:</strong> to manage Your registration as a user of the Service. The Personal Data You provide can give You access to different functionalities of the Service that are available to You as a registered user.</p>\n</li>\n<li>\n<p><strong>For the performance of a contract:</strong> the development, compliance and undertaking of the purchase contract for the products, items or services You have purchased or of any other contract with Us through the Service.</p>\n</li>\n<li>\n<p><strong>To contact You:</strong> To contact You by email, telephone calls, SMS, or other equivalent forms of electronic communication, such as a mobile application''s push notifications regarding updates or informative communications related to the functionalities, products or contracted services, including the security updates, when necessary or reasonable for their implementation.</p>\n</li>\n<li>\n<p><strong>To provide You</strong> with news, special offers, and general information about other goods, services and events which We offer that are similar to those that you have already purchased or inquired about unless You have opted not to receive such information.</p>\n</li>\n<li>\n<p><strong>To manage Your requests:</strong> To attend and manage Your requests to Us.</p>\n</li>\n<li>\n<p><strong>For business transfers:</strong> We may use Your information to evaluate or conduct a merger, divestiture, restructuring, reorganization, dissolution, or other sale or transfer of some or all of Our assets, whether as a going concern or as part of bankruptcy, liquidation, or similar proceeding, in which Personal Data held by Us about our Service users is among the assets transferred.</p>\n</li>\n<li>\n<p><strong>For other purposes</strong>: We may use Your information for other purposes, such as data analysis, identifying usage trends, determining the effectiveness of our promotional campaigns and to evaluate and improve our Service, products, services, marketing and your experience.</p>\n</li>\n</ul>\n<p>We may share Your personal information in the following situations:</p>\n<ul>\n<li><strong>With Service Providers:</strong> We may share Your personal information with Service Providers to monitor and analyze the use of our Service,  to contact You.</li>\n<li><strong>For business transfers:</strong> We may share or transfer Your personal information in connection with, or during negotiations of, any merger, sale of Company assets, financing, or acquisition of all or a portion of Our business to another company.</li>\n<li><strong>With Affiliates:</strong> We may share Your information with Our affiliates, in which case we will require those affiliates to honor this Privacy Policy. Affiliates include Our parent company and any other subsidiaries, joint venture partners or other companies that We control or that are under common control with Us.</li>\n<li><strong>With business partners:</strong> We may share Your information with Our business partners to offer You certain products, services or promotions.</li>\n<li><strong>With other users:</strong> when You share personal information or otherwise interact in the public areas with other users, such information may be viewed by all users and may be publicly distributed outside.</li>\n<li><strong>With Your consent</strong>: We may disclose Your personal information for any other purpose with Your consent.</li>\n</ul>\n<h3>Retention of Your Personal Data</h3>\n<p>The Company will retain Your Personal Data only for as long as is necessary for the purposes set out in this Privacy Policy. We will retain and use Your Personal Data to the extent necessary to comply with our legal obligations (for example, if we are required to retain your data to comply with applicable laws), resolve disputes, and enforce our legal agreements and policies.</p>\n<p>The Company will also retain Usage Data for internal analysis purposes. Usage Data is generally retained for a shorter period of time, except when this data is used to strengthen the security or to improve the functionality of Our Service, or We are legally obligated to retain this data for longer periods.</p>\n<h3>Transfer of Your Personal Data</h3>\n<p>Your information, including Personal Data, is processed at the Company''s operating offices and in any other places where the parties involved in the processing are located. It means that this information may be transferred to — and maintained on — computers located outside of Your state, province, country or other governmental jurisdiction where the data protection laws may differ from those from Your jurisdiction.</p>\n<p>Your consent to this Privacy Policy followed by Your submission of such information represents Your agreement to that transfer.</p>\n<p>The Company will take all steps reasonably necessary to ensure that Your data is treated securely and in accordance with this Privacy Policy and no transfer of Your Personal Data will take place to an organization or a country unless there are adequate controls in place including the security of Your data and other personal information.</p>\n<h3>Delete Your Personal Data</h3>\n<p>You have the right to delete or request that We assist in deleting the Personal Data that We have collected about You.</p>\n<p>Our Service may give You the ability to delete certain information about You from within the Service.</p>\n<p>You may update, amend, or delete Your information at any time by signing in to Your Account, if you have one, and visiting the account settings section that allows you to manage Your personal information. You may also contact Us to request access to, correct, or delete any personal information that You have provided to Us.</p>\n<p>Please note, however, that We may need to retain certain information when we have a legal obligation or lawful basis to do so.</p>\n<h3>Disclosure of Your Personal Data</h3>\n<h4>Business Transactions</h4>\n<p>If the Company is involved in a merger, acquisition or asset sale, Your Personal Data may be transferred. We will provide notice before Your Personal Data is transferred and becomes subject to a different Privacy Policy.</p>\n<h4>Law enforcement</h4>\n<p>Under certain circumstances, the Company may be required to disclose Your Personal Data if required to do so by law or in response to valid requests by public authorities (e.g. a court or a government agency).</p>\n<h4>Other legal requirements</h4>\n<p>The Company may disclose Your Personal Data in the good faith belief that such action is necessary to:</p>\n<ul>\n<li>Comply with a legal obligation</li>\n<li>Protect and defend the rights or property of the Company</li>\n<li>Prevent or investigate possible wrongdoing in connection with the Service</li>\n<li>Protect the personal safety of Users of the Service or the public</li>\n<li>Protect against legal liability</li>\n</ul>\n<h3>Security of Your Personal Data</h3>\n<p>The security of Your Personal Data is important to Us, but remember that no method of transmission over the Internet, or method of electronic storage is 100% secure. While We strive to use commercially reasonable means to protect Your Personal Data, We cannot guarantee its absolute security.</p>\n<h2>Detailed Information on the Processing of Your Personal Data</h2>\n<p>The Service Providers We use may have access to Your Personal Data. These third-party vendors collect, store, use, process and transfer information about Your activity on Our Service in accordance with their Privacy Policies.</p>\n<h3>Usage, Performance and Miscellaneous</h3>\n<p>We may use third-party Service Providers to maintain and improve our Service.</p>\n<ul>\n<li>\n<p><strong>Google Places</strong></p>\n<p>Google Places is a service that returns information about places using HTTP requests. It is operated by Google</p>\n<p>Google Places service may collect information from You and from Your Device for security purposes.</p>\n<p>The information gathered by Google Places is held in accordance with the Privacy Policy of Google: <a href=\"https://www.google.com/intl/en/policies/privacy/\" rel=\"external nofollow noopener\" target=\"_blank\">https://www.google.com/intl/en/policies/privacy/</a></p>\n</li>\n</ul>\n<h2>Children''s Privacy</h2>\n<p>Our Service does not address anyone under the age of 13. We do not knowingly collect personally identifiable information from anyone under the age of 13. If You are a parent or guardian and You are aware that Your child has provided Us with Personal Data, please contact Us. If We become aware that We have collected Personal Data from anyone under the age of 13 without verification of parental consent, We take steps to remove that information from Our servers.</p>\n<p>If We need to rely on consent as a legal basis for processing Your information and Your country requires consent from a parent, We may require Your parent''s consent before We collect and use that information.</p>\n<h2>Links to Other Websites</h2>\n<p>Our Service may contain links to other websites that are not operated by Us. If You click on a third party link, You will be directed to that third party''s site. We strongly advise You to review the Privacy Policy of every site You visit.</p>\n<p>We have no control over and assume no responsibility for the content, privacy policies or practices of any third party sites or services.</p>\n<h2>Changes to this Privacy Policy</h2>\n<p>We may update Our Privacy Policy from time to time. We will notify You of any changes by posting the new Privacy Policy on this page.</p>\n<p>We will let You know via email and/or a prominent notice on Our Service, prior to the change becoming effective and update the \"Last updated\" date at the top of this Privacy Policy.</p>\n<p>You are advised to review this Privacy Policy periodically for any changes. Changes to this Privacy Policy are effective when they are posted on this page.</p>\n<h2>Contact Us</h2>\n<p>If you have any questions about this Privacy Policy, You can contact us:</p>\n<ul>\n<li>By email: <a href=\"mailto:shindoranesub@gmail.com\">shindoranesub@gmail.com</a></li>\n</ul>","showInFooter":true,"createdAt":"2026-08-10T17:38:46.525Z"}');
INSERT OR REPLACE INTO [pages] (id, data) VALUES ('0c8ffb03-7480-4126-8d6e-c18c7a4cbb4f', '{"_id":"6a7d8da89babfb3422d1abcc","title":"Disclaimer","slug":"disclaimer","content":"<p>&nbsp;</p><p>Bahasa Indonesia:&nbsp;<strong data-end=\"250\" data-start=\"236\">Disclaimer</strong></p><p data-end=\"379\" data-start=\"236\">\nWebsite ini adalah situs <strong data-end=\"304\" data-start=\"280\">fansub non-komersial</strong> yang dibuat oleh penggemar untuk tujuan hiburan dan pembelajaran bahasa.</p>\n<p data-end=\"532\" data-start=\"386\">Seluruh video, karakter, dan materi terkait <strong data-end=\"442\" data-start=\"430\">Doraemon</strong> dan <strong data-end=\"467\" data-start=\"447\">Crayon Shin-chan</strong> merupakan hak cipta dari pemegang lisensi resmi masing-masing.</p>\n<p data-end=\"634\" data-start=\"539\">Kami <strong data-end=\"592\" data-start=\"544\">tidak menyimpan file video di server sendiri</strong>. Semua video berasal dari pihak ketiga.</p>\n<p data-end=\"755\" data-start=\"641\">Apabila ada pihak yang merasa keberatan atau dirugikan, silakan menghubungi kami untuk penghapusan konten terkait. <a href=\"mailto:shindoranesub@gmail.com\">shindoranesub@gmail.com</a></p><p>Language Inggris :Disclaimer</p><p>This website is a non-commercial fansub site created by fans for entertainment and language learning purposes.</p><p>All videos, characters, and related materials about Doraemon and Crayon Shin-chan are copyrighted by their respective licensees.</p><p>We do not store video files on our own servers. All videos are sourced from third parties.</p><p>If anyone has any objections or feels aggrieved, please contact us to remove the content. <a href=\"mailto:shindoranesub@gmail.com\">shindoranesub@gmail.com</a></p>","showInFooter":true,"id":"0c8ffb03-7480-4126-8d6e-c18c7a4cbb4f","createdAt":"2026-08-13T09:26:00.457Z"}');
